const quizTitles = [
  "Foundations",
  "Core Concepts",
  "Skills Practice",
  "Applications",
  "Analysis",
  "Problem Solving",
  "Knowledge Check",
  "Concept Review",
  "Applied Practice",
  "Comprehensive Review",
];

export function getSubjectQuizTemplates(
  subjectCode: string,
): Array<{ title: string; description: string; questions: QuizQuestionInput[] }> | null {
  const templates = subjectTemplates[subjectCode];
  if (!templates?.length) return null;

  return quizTitles.map((quizTitle, quizIndex) => {
    const template = templates[quizIndex % templates.length];
    const questionCount = Math.min(5, template.questions.length);
    const questions = Array.from({ length: questionCount }, (_, index) =>
      template.questions[(quizIndex + index) % template.questions.length]
    );
    return {
      title: `Quiz ${String(quizIndex + 1).padStart(2, "0")} · ${quizTitle} · ${template.focus}`,
      description: `Subject-based multiple-choice questions: ${template.focus}.`,
      questions,
    };
  });
}
